import React from 'react';
import './BookCard.css';
const BookCard = ({ title,description,image }) => {
    const imagePath = require(`../../../assents/images/${image}`);
    return (
        <div className="book-card">
            <img src={imagePath} alt={title} className="book-image" />
            <h3>{title}</h3>
            <p>{description}</p>
            
        </div>
    );
};

export default BookCard;
